steps.script:
var main = tree.root.get_node("Main")
var log := []
for i in range(10):
	main._on_ai_suggestion_pressed()
	var d: Dictionary = main._ai_suggestion_panel._decision
	var t := str(d.get("type", ""))
	if t == "" or t.begins_with("END_"):
		log.append(t + "(stop)")
		break
	if main._ai_suggestion_panel._accept_btn.disabled:
		log.append(t + ":DISABLED " + main._ai_suggestion_panel._accept_btn.tooltip_text)
		break
	main._on_ai_suggestion_accept()
	var st: String = main._ai_suggestion_panel._accept_status.text
	log.append(t + (":ok" if st.begins_with("✔") else ":FAIL " + st))
	if not st.begins_with("✔"):
		break
print("ACCEPT-CHAIN ", log)
main.set_meta("acc_chain", str(log))
return ("FAIL" in str(log)) or ("DISABLED" in str(log))
